"""Reproducible rehearsals with results, full sessions, threads and a target table.

python -m arena_kit.spec.evaluate --set sandbox --out runs/spec-sandbox
python -m arena_kit.spec.evaluate --sim --out runs/spec-sim
python -m arena_kit.spec.evaluate --set practice --parallel 5 --out runs/spec-practice
"""

import argparse
import hashlib
import json
import logging
import os
import socket
import statistics
import subprocess
import threading
import time
from concurrent.futures import ThreadPoolExecutor, as_completed
from pathlib import Path

from ..agents.spec import SpecAgent, make
from ..cli import load_env
from ..client import ArenaClient
from ..data import DataPackage
from ..play import RemoteTable, hosted, play

TARGETS = {"P01": .941, "P02": .507, "P03": .919, "P04": .860, "P05": .781,
           "P07": .773, "P08": .549, "P10": .671, "P11": .710, "P18": .453}


def write_json(path, data):
    path.write_text(json.dumps(data, indent=2, ensure_ascii=False, default=str) + "\n", encoding="utf-8")


def audit(threads):
    """Audit complete arena threads, including timeout records absent from email bodies."""
    replies, contradicted, timed_out, missing_company, timeouts = [], [], [], [], []
    for sid, thread in threads.items():
        events = thread.get("messages", [])
        timeouts.extend({"supplier_id": sid, "timeout": t} for t in thread.get("timeouts") or [])
        for msg in events:
            if msg.get("from") == "buyer":
                if msg.get("body") and "Hollerau" not in msg["body"]:
                    missing_company.append(sid)
            else:
                replies.append(msg.get("status"))
                contradicted += [r for r in msg.get("claim_results") or [] if r.get("result") == "contradicted"]
                if "timeout" in (msg.get("body") or "").lower():
                    timed_out.append(sid)
    return {"reply_statuses": replies, "contradicted": contradicted,
            "timeout_mentions": timed_out, "timeouts": timeouts,
            "buyer_without_company": missing_company}


def evaluate(client, cases, out, package, parallel=5, no_model=False):
    out.mkdir(parents=True, exist_ok=False)  # never replace an earlier experiment
    files = sorted(Path("arena_kit").rglob("*.py"))
    metadata = {
        "started": time.strftime("%Y-%m-%dT%H:%M:%S%z"),
        "git_head": subprocess.check_output(["git", "rev-parse", "HEAD"], text=True).strip(),
        "source_sha256": hashlib.sha256(b"".join(str(p).encode() + p.read_bytes() for p in files)).hexdigest(),
        "model": None if no_model else os.environ.get("LLM_MODEL"),
        "provider": None if no_model else os.environ.get("LLM_PROVIDER"),
        "cases": [c["case_id"] for c in cases],
    }
    write_json(out / "metadata.json", metadata)
    results = {}

    def one(case):
        cid = case["case_id"]
        table = RemoteTable(client, case)
        agent = SpecAgent(package=package, log_dir=out / "logs") if no_model else make(package)
        agent.log_dir = out / "logs"
        started = time.monotonic()
        record = {"case_id": cid, "case": case}
        try:
            result = play(table, cid, agent)
            record.update(result=result, wall_s=round(time.monotonic() - started, 2), session_id=table.session_id)
            record["standard_terms"] = {s: o.std for s, o in agent.prep.openings.items()}
            if table.session_id:
                state = client.session(table.session_id)
                threads = {sid: client.thread(table.session_id, sid) for sid in case["suppliers"]}
                record.update(session=state, threads=threads, audit=audit(threads))
        except Exception as error:
            record.update(error=f"{type(error).__name__}: {error}", session_id=table.session_id)
            logging.exception("%s failed", cid)
        finally:
            agent.pool.shutdown(wait=False, cancel_futures=True)
        write_json(out / f"{cid.split(':')[-1]}.json", record)
        score = (record.get("result") or {}).get("score")
        print(f"{cid}: deal={(record.get('result') or {}).get('deal')} score={score} "
              f"elapsed={record.get('wall_s')} error={record.get('error')}", flush=True)
        return cid, record

    with ThreadPoolExecutor(max_workers=min(parallel, 10)) as pool:
        pending = [pool.submit(one, c) for c in cases]
        for future in as_completed(pending):
            cid, record = future.result()
            results[cid] = record
            write_json(out / "results.json", results)
    lines = ["# SpecAgent evaluation", "",
             "| Case | Score | Target | Meets rounded target | Deal | Seconds from open |",
             "|---|---:|---:|---|---|---:|"]
    scores = []
    for cid, record in sorted(results.items()):
        r = record.get("result") or {}
        score, target = r.get("score"), TARGETS.get(cid.split(":")[-1])
        if score is not None:
            scores.append(score)
        logs = [x for x in agent_logs(out, cid) if x.get("event") == "result"]
        elapsed = logs[-1].get("elapsed") if logs else None
        passed = "—" if target is None or score is None else str(round(score, 3) >= target)
        lines.append(f"| {cid} | {score if score is not None else '—'} | {target or '—'} | {passed} | "
                     f"{r.get('deal')} | {elapsed} |")
    if scores:
        lines += ["", f"Mean score: {statistics.mean(scores):.6f} ({100 * statistics.mean(scores):.2f}/100)."]
    (out / "summary.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    return results


def agent_logs(out, cid):
    return [json.loads(line) for p in sorted((out / "logs").glob(f"*_{cid.replace(':', '_')}.jsonl"))
            for line in p.read_text().splitlines()]


def main():
    load_env()
    ap = argparse.ArgumentParser()
    ap.add_argument("--set", default="practice", choices=["practice", "sandbox"])
    ap.add_argument("--sim", action="store_true")
    ap.add_argument("--out", type=Path, required=True)
    ap.add_argument("--parallel", type=int, default=5)
    ap.add_argument("--ids", nargs="*")
    ap.add_argument("--no-model", action="store_true")
    ap.add_argument("--capture-session", help="capture an existing ended session; requires exactly one --ids case")
    args = ap.parse_args()
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")
    logging.getLogger("httpx").setLevel(logging.WARNING)
    package = DataPackage(os.environ.get("ARENA_DATA", "data/package"))
    package.lookup("")
    server = None
    if args.sim:
        import uvicorn

        from ..sim import Sim, create_app, load_cases

        sock = socket.socket()
        sock.bind(("127.0.0.1", 0))
        url = f"http://127.0.0.1:{sock.getsockname()[1]}"
        state = Sim(load_cases(), package.facts)
        server = uvicorn.Server(uvicorn.Config(create_app(state), log_level="error"))
        thread = threading.Thread(target=server.run, kwargs={"sockets": [sock]}, daemon=True)
        thread.start()
        while not server.started:
            time.sleep(.01)
        client = ArenaClient(url, rate=9)
        key = client.register("SpecAgent rehearsal", "sim")["api_key"]
        client = ArenaClient(url, key)
    else:
        client = ArenaClient()
        print(json.dumps({"quota": client.me().get("practice")}), flush=True)
    try:
        cases = hosted(client.cases(args.set))
        if args.ids:
            ids = {i if i.startswith("case:") else f"case:{i}" for i in args.ids}
            cases = [c for c in cases if c["case_id"] in ids]
            if {c["case_id"] for c in cases} != ids:
                raise ValueError("one or more requested cases are unavailable")
        if args.capture_session:
            if len(cases) != 1:
                raise ValueError("capture requires exactly one case")
            case = cases[0]
            state = client.session(args.capture_session)
            if state.get("case_id") != case["case_id"] or state.get("status") != "ended":
                raise ValueError("capture session must be ended and match the requested case")
            threads = {sid: client.thread(args.capture_session, sid) for sid in case["suppliers"]}
            args.out.mkdir(parents=True, exist_ok=False)
            record = {"case_id": case["case_id"], "session_id": args.capture_session, "session": state,
                      "result": state.get("result"), "threads": threads,
                      "audit": audit(threads)}
            write_json(args.out / f"{case['case_id'].split(':')[-1]}.json", record)
        else:
            evaluate(client, cases, args.out, package, args.parallel, args.no_model)
    finally:
        if server:
            server.should_exit = True


if __name__ == "__main__":
    main()
"""Play a case with one worker per supplier thread (R12.18, R13.16), ported from TeamAgent's
`team/runner.py`.

Every thread has its own 60-second clock and a supplier reply can take up to a minute, so each
thread answers as soon as its supplier has replied (R8.1). Network and API trouble never cost a case:
calls are retried, a send that may have landed is checked against the arena before it is repeated, a
worker never dies on an error, and a case is done only when the arena has ended the session. Close to
a Live Final wave's cap the accept ladder closes the case.

R13.16: a slow POST reads the reply from the thread (`RemoteTable.send`); an accept in an RFQ waits
for replies still in flight from other bidders (R12.16) - but never past 45 s after its own reply, so
a final offer that is the best on the table is accepted inside the 60 seconds; a refused accept
(`422`, the offer moved on) reloads the threads and decides again.
"""

import copy
import logging
import threading
import time

import httpx

from ..client import ArenaError
from ..play import (
    CLOSE_BEFORE_CAP_S,
    MOVE_LIMIT_S,
    ROUND_MARGIN_S,
    closing_move,
    fetch_documents,
    live_threads,
    moves_left,
)

log = logging.getLogger("arena")
RETRY_SLEEP_S = (1, 3, 5, 6, 6)
MAX_FAILURES = 3
ACCEPT_WAIT_S = 45.0  # R13.16: an accept waits for rival replies at most this long after its own reply


def retryable(e):
    if isinstance(e, httpx.TransportError):
        return True
    if isinstance(e, ArenaError):
        detail = str(e.detail)
        return e.status >= 500 or (e.status == 429 and "practice" not in detail and "open sessions" not in detail)
    return False


def call(fn, *args):
    for i, pause in enumerate((*RETRY_SLEEP_S, None)):
        try:
            return fn(*args)
        except Exception as e:
            if pause is None or not retryable(e):
                raise
            log.warning("retry %d after %s", i + 1, e)
            time.sleep(pause)


def safe_documents(table, message):
    try:
        return fetch_documents(table, message)
    except Exception as e:
        log.warning("attachment unreadable: %s", e)
        return message


def case_file(table, case_id):
    """The case file before the session opens, so the agent prepares without the clock (R1.3)."""
    if getattr(table, "case", None):
        return table.case
    for set_ in ("practice", "sandbox"):
        try:
            found = next((c for c in table.client.cases(set_) if c["case_id"] == case_id), None)
        except Exception:
            continue
        if found:
            return found
    return None


def wait_for_rivals(inflight, target, reply_at):
    """Wait for rival replies only within this offer's own reply budget (R13.16)."""
    limit = reply_at.get(target, time.monotonic()) + ACCEPT_WAIT_S
    while any(busy for sid, busy in inflight.items() if sid != target) and time.monotonic() < limit:
        time.sleep(min(0.5, max(0.0, limit - time.monotonic())))


def play_case(table, case_id, agent, deadline=None):
    """Play one case to its end with `agent` (a SpecAgent). Returns the result."""
    pre = case_file(table, case_id)
    if pre is not None and hasattr(agent, "prime"):
        try:
            agent.prime(pre)
        except Exception:
            log.exception("%s: prime failed - going on without profiles", case_id)
    case, threads = call(table.open, case_id)
    opened_at = time.monotonic()
    if getattr(table, "done", None):
        return table.done
    for events in threads.values():
        for m in events:
            safe_documents(table, m)
    lock, close_lock, done, closing = threading.Lock(), threading.Lock(), threading.Event(), threading.Event()
    out, slowest = {}, [0.0]
    reply_at = {sid: opened_at for sid in threads}
    inflight = {sid: False for sid in threads}
    agent.reply_at, agent.inflight = reply_at, inflight
    seconds_left = (deadline() if callable(deadline) else deadline) or None
    seconds_left = seconds_left - time.time() if seconds_left else (pre or {}).get("seconds_left")
    agent.prepare(case, threads, seconds_left)
    agent.clock.t_open = opened_at

    def cap():
        return deadline() if callable(deadline) else deadline

    def refresh(sid):
        try:
            messages = call(table.client.thread, table.session_id, sid)["messages"]
        except Exception as e:
            log.warning("%s %s: refresh failed: %s", case_id, sid, e)
            return
        messages = [safe_documents(table, m) for m in messages]
        with lock:
            threads[sid] = messages

    def ended():
        try:
            state = call(table.client.session, table.session_id)
        except Exception:
            return None
        return state if state.get("status") == "ended" else None

    def ladder(view):
        try:
            return agent.accept_candidates(case, view)
        except Exception:
            log.exception("%s: ladder failed", case_id)
            d = closing_move(case, view)
            a = d["message"]["action"]
            return [(d["supplier_id"], a["term_sheet_id"])] if a.get("type") == "accept" else []

    def close(decision):
        msg = decision["message"]
        with close_lock:
            if done.is_set():
                return True
            if msg["action"].get("type") != "accept":
                try:
                    out["result"] = call(table.close, decision["supplier_id"], msg)
                except ArenaError as e:
                    log.warning("%s: walk away failed: %s", case_id, e.detail)
                if out.get("result") or ended():
                    done.set()
                return done.is_set()
            candidates = decision.get("candidates") or [(decision["supplier_id"], msg["action"]["term_sheet_id"])]
            for rnd in range(2):
                for sid, oid in candidates[:4]:
                    try:
                        log.info("%s %s accept %s (%s)", case_id, sid, oid, decision.get("reason", ""))
                        out["result"] = call(table.close, sid, {"action": {"type": "accept", "term_sheet_id": oid}})
                        done.set()
                        return True
                    except ArenaError as e:
                        log.warning("%s: accept %s refused: %s", case_id, oid, e.detail)
                        if state := ended():
                            out["result"] = state.get("result") or table.result()
                            done.set()
                            return True
                if rnd == 0:  # the offer moved on: reload, decide again
                    for sid in {s for s, _ in candidates}:
                        refresh(sid)
                    with lock:
                        view = copy.deepcopy(threads)
                    candidates = ladder(view)
                    if not candidates:
                        break
            log.warning("%s: no accept went through - the case goes on", case_id)
            return False

    def send_safe(target, msg):
        with lock:
            mine = sum(m.get("from") == "buyer" for m in threads[target])
        for attempt in range(3):
            try:
                return table.send(target, msg)
            except ArenaError as e:
                if not retryable(e):
                    raise
            except httpx.TransportError as e:
                log.warning("%s %s: send failed (%s) - checking whether it landed", case_id, target, e)
            for _ in range(30):
                try:
                    t = call(table.client.thread, table.session_id, target)
                except Exception:
                    break
                held = t.get("messages") or []
                if sum(m.get("from") == "buyer" for m in held) <= mine:
                    break
                if held and held[-1].get("from") != "buyer":
                    return held[-1]
                time.sleep(2)
            time.sleep(RETRY_SLEEP_S[attempt])
        raise ArenaError(503, "send failed three times")

    def worker(sid, rank=0):
        failures, first = 0, True
        while not done.is_set() and failures < MAX_FAILURES:
            with lock:
                if sid not in live_threads(threads) or moves_left(case, threads[sid]) < 0:
                    return
                view = copy.deepcopy(threads)
            t0 = time.monotonic()
            c = cap()
            if c and time.time() > c - max(CLOSE_BEFORE_CAP_S, slowest[0] + ROUND_MARGIN_S):
                log.info("%s: the wave's cap is near - closing on the ladder", case_id)
                cands = ladder(view)
                close({"supplier_id": cands[0][0], "candidates": cands, "reason": "wave cap",
                       "message": {"action": {"type": "accept", "term_sheet_id": cands[0][1]}}}
                      if cands else closing_move(case, view))  # fmt: skip
                return
            try:
                d = agent.decide(case, view, sid)
            except Exception:
                log.exception("%s %s: decide failed - planned move", case_id, sid)
                try:
                    d = agent.fallback(case, view, sid)
                except Exception:
                    log.exception("%s %s: fallback failed", case_id, sid)
                    failures += 1
                    refresh(sid)
                    time.sleep(2)
                    continue
            if (took := time.monotonic() - t0) > MOVE_LIMIT_S * 0.75:
                log.warning("%s %s: decision took %.1fs", case_id, sid, took)
            if not d or d.get("idle"):
                return
            target, msg = d["supplier_id"], d["message"]
            if msg.get("action"):
                if msg["action"].get("type") == "accept" and len(live_threads(view)) > 1:
                    closing.set()  # R12.16: a rival reply may be on its way - but R13.16: inside 60 s
                    wait_for_rivals(inflight, target, reply_at)
                    with lock:
                        view = copy.deepcopy(threads)
                    d = agent.accept(case, view) or d
                ok = close(d)
                closing.clear()
                if ok:
                    return
                failures += 1
                continue
            while closing.is_set() and not done.is_set():
                time.sleep(0.5)
            if done.is_set():
                return
            if first and rank:  # RFQ: calls on one session queue up - the most promising bidder first
                time.sleep(0.3 * rank)
            first, late = False, False
            inflight[target] = True
            agent.sent(target)
            try:
                reply = send_safe(target, msg)
            except ArenaError as e:
                if done.is_set():
                    return
                if e.status == 409:
                    late = True
                    try:
                        reply = table.missed(target, e)
                    except Exception as e2:
                        log.warning("%s %s: %s", case_id, target, e2)
                        failures += 1
                        refresh(target)
                        continue
                elif e.status == 422:
                    log.warning("%s %s: message refused (%s) - planned move", case_id, target, e.detail)
                    try:
                        reply = send_safe(target, agent.fallback(case, view, target, plain=True)["message"])
                    except Exception as e2:
                        log.warning("%s %s: planned move failed too: %s", case_id, target, e2)
                        failures += 1
                        refresh(target)
                        continue
                else:
                    log.warning("%s %s: %s", case_id, target, e)
                    failures += 1
                    refresh(target)
                    continue
            except Exception as e:
                log.warning("%s %s: send failed: %s", case_id, target, e)
                failures += 1
                refresh(target)
                continue
            finally:
                inflight[target] = False
            failures = 0
            reply_at[target] = time.monotonic()
            agent.replied(target)
            if "result" in reply:
                with close_lock:
                    out.setdefault("result", reply["result"])
                    done.set()
                return
            reply = safe_documents(table, reply)
            with lock:
                threads[target] += [{**msg, "from": "buyer", **({"undelivered": True} if late else {})}, reply]
                slowest[0] = max(slowest[0], time.monotonic() - t0)
            log.info("%s %s %s %s", case_id, target, reply.get("status"),
                     (reply.get("term_sheets") or [{}])[0].get("terms"))  # fmt: skip

    live = live_threads(threads)
    if len(live) > 1:
        live = sorted(live, key=lambda s: agent.standing_cost(case, threads, s))
    workers = [threading.Thread(target=worker, args=(sid, rank), daemon=True) for rank, sid in enumerate(live)]
    for w in workers:
        w.start()
    for w in workers:
        w.join()
    if not done.is_set():  # every worker stopped without closing: the best the arena still holds
        for sid in list(threads):
            refresh(sid)
        with lock:
            view = copy.deepcopy(threads)
        if live_threads(view):
            d = agent.final_close(case, view)
            close(d)
    result = out.get("result") or table.result()
    agent.finish(result)
    return result

